int dp[9][9][9][9]; 

const int moves = 5;
const int movesv[moves][4] = {
    {2, 1, 0, 2}, 
    {1, 1, 1, 1}, 
    {0, 0, 2, 1}, 
    {0, 3, 0, 0}, 
    {1, 0, 0, 1}  
};

int win(int a, int b, int c, int d) {
    int &res = dp[a][b][c][d];
    if (res != -1) return res;

    for (int mv = 0; mv < moves; ++mv) {
        int na = a - movesv[mv][0];
        int nb = b - movesv[mv][1];
        int nc = c - movesv[mv][2];
        int nd = d - movesv[mv][3];
        if (na >= 0 && nb >= 0 && nc >= 0 && nd >= 0) {

            if (!win(na, nb, nc, nd)) {
                res = 1;
                return res;
            }
        }
    }

    res = 0;
    return res;
}

int main() {
    for (int a = 0; a <= 8; ++a)
        for (int b = 0; b <= 8; ++b)
            for (int c = 0; c <= 8; ++c)
                for (int d = 0; d <= 8; ++d)
                    dp[a][b][c][d] = -1;

    int n;
    if (!(cin >> n)) return 0;
    while (n--) {
        int a,b,c,d;
        if(!(cin >> a >> b >> c >> d)) {
            cout << "B";
            break;
        };
        if(max({a, b, c, d}) > 8) {
            return 1;
        }
        a = min(max(a,0),8);
        b = min(max(b,0),8);
        c = min(max(c,0),8);
        d = min(max(d,0),8);
        if (win(a,b,c,d)) cout << "A\n"; else cout << "B\n";
    }
}